EXPORT ZZT_TRISCREEN() BEGIN
Xmin:=0; Xmax:=318; Ymin:=-218; Ymax:=0;
RECT_P(#020406h);
LOCAL painted:=TRIANGLE(-1,0,5,0,-1,-6,#FF0000h,#00FF00h,#0000FFh,128), x, y, pixels:={};
FOR y FROM 0 TO 6 DO
  FOR x FROM 0 TO 6 DO
    pixels:=CONCAT(pixels,{B→R(GETPIX_P(x,y))});
  END;
END;
RETURN {painted,pixels};
END;

EXPORT ZZT_TALLRGB() BEGIN
RECT_P(#020406h); LOCAL r,x,y,a:={};
r:=TRIANGLE_P(1,-70000,5,2,2,6,#FF0000h,#00FF00h,#0000FFh,128);
FOR y FROM 0 TO 6 DO
 FOR x FROM 0 TO 6 DO
  a:=CONCAT(a,{B→R(GETPIX_P(x,y))});
 END;
END;
RETURN {r,a}; END;

